"use strict";
const CONSENT_KEYS=['ad_storage','analytics_storage','ad_user_data','ad_personalization'];
const CONSENT_CASES=[
{id:'banner',title:P('Banner hai, wiring nahi','A banner without wiring'),fact:P('Reject select hua. Tag Assistant mein koi consent update nahi; sirf banner hide hui.','Reject was selected. Tag Assistant shows no consent update; only the banner disappeared.'),options:[P('Banner hide hui to test pass','Hiding the banner passes the test'),P('CMP choice se actual consent update aur tag behavior verify karo','Verify the actual consent update and tag behavior from the CMP choice'),P('Reject ko Accept bana do','Replace Reject with Accept')],answer:1,why:P('Visible UI aur tag ki state alag checks hain. Choice ko implementation tak trace karo.','The visible UI and tag state are separate checks. Trace the choice through the implementation.')},
{id:'late',title:P('Default der se aya','Default arrived late'),fact:P('Sequence: measurement request → default denied.','Sequence: measurement request → default denied.'),options:[P('Default pehle set karo; earlier request aur region/config inspect karo','Set the default first; inspect the earlier request and region/configuration'),P('Baad ka denied pehle request ko undo karta hai','A later denied state undoes the earlier request'),P('Default kabhi matter nahi karta','Default timing never matters')],answer:0,why:P('Baad ki command past ko undo nahi karti. Clean session mein sequence dobara verify karo.','A later command does not undo the past. Recheck ordering in a clean session.')},
{id:'advanced',title:P('Denied lekin network request?','Denied but a network request?'),fact:P('Advanced setup, early denied defaults. Google tag ka cookieless ping observe hua.','Advanced setup with early denied defaults. A cookieless Google-tag ping is observed.'),options:[P('Har request consent failure ki proof hai','Every request proves consent failure'),P('Denied mein kabhi data nahi jata','Denied always means no data is sent'),P('Expected restricted behavior se compare karo; request contents aur actual storage separately inspect karo','Compare with expected restricted behavior; inspect request contents and actual storage separately')],answer:2,why:P('Advanced denied behavior mein cookieless pings possible hain. Is se zero data transfer ya compliance prove nahi hoti.','Advanced denied behavior can include cookieless pings. This establishes neither zero data transfer nor compliance.')},
{id:'basic',title:P('Basic mode aur no choice','Basic mode with no choice'),fact:P('Basic implementation ka design Google tags ko consent tak block karta hai. User ne abhi choose nahi kiya.','This basic implementation is designed to block Google tags until consent. The visitor has not chosen yet.'),options:[P('Google tags ko abhi load/firing se block rakho; gating verify karo','Keep Google tags blocked from loading/firing; verify the gate'),P('Advanced jaisi pings ko basic design ka expected result keh do','Call advanced-style pings the expected basic result'),P('No choice ko grant samjho','Treat no choice as a grant')],answer:0,why:P('Basic aur advanced implementation ki expected network behavior ek nahi. Selected design ke mutabiq test karo.','Basic and advanced implementations do not have identical expected network behavior. Test against the selected design.')},
{id:'partial',title:P('Storage aur personalization alag','Storage and personalization differ'),fact:P('ad_storage granted hai. ad_user_data aur ad_personalization denied hain.','ad_storage is granted. ad_user_data and ad_personalization are denied.'),options:[P('Storage granted se sab purposes granted hain','Storage granted means all purposes are granted'),P('Har consent type ko apne purpose ke liye respect aur verify karo','Respect and verify each consent type for its own purpose'),P('Denied flags delete kar do','Delete the denied flags')],answer:1,why:P('Flags ko ek master permission mat samjho. CMP mapping aur tag settings ka test record rakho.','Do not treat the flags as one master permission. Keep a test record of CMP mapping and tag settings.')},
{id:'withdraw',title:P('Choice wapas badal di','The choice was withdrawn'),fact:P('User ne Accept ke baad settings se Reject kiya. Banner badli, lekin tag state granted hi rahi.','After accepting, the visitor rejected in settings. The banner changed, but tag state stayed granted.'),options:[P('Pehla Accept forever hai','The first acceptance lasts forever'),P('Sirf banner text enough hai','Banner text alone is enough'),P('Withdrawal update aur future events, navigation, saved choice aur non-Google tags retest karo','Retest the withdrawal update, future events, navigation, saved choice and non-Google tags')],answer:2,why:P('Choice change ko bhi implementation tak pohanchna chahiye. Consent mode har third-party tag ko automatically manage nahi karta.','Changed choices must reach the implementation too. Consent mode does not automatically manage every third-party tag.')}
];
let consentCase=0;
function cleanConsent(v){const r={mode:'basic',timing:'early',choice:'none',update:true,answers:{},notes:''};if(!v||typeof v!=='object')return r;for(const [k,allowed]of [['mode',['basic','advanced']],['timing',['early','late']],['choice',['none','accept','reject']]])if(allowed.includes(v[k]))r[k]=v[k];if(typeof v.update==='boolean')r.update=v.update;if(typeof v.notes==='string')r.notes=v.notes.slice(0,5000);for(const c of CONSENT_CASES)if(Number.isInteger(v.answers?.[c.id])&&v.answers[c.id]>=0&&v.answers[c.id]<3)r.answers[c.id]=v.answers[c.id];return r;}
function consentRecord(){return state.clinic.consent;}
function consentSequence(raw){const c=cleanConsent(raw),before=c.mode==='basic'?'blocked':c.timing==='late'?'unknown':'restricted';const chosen=c.choice!=='none',updated=chosen&&c.update;let after;if(!chosen||c.choice==='reject')after=c.mode==='basic'?'blocked':'restricted';else after=updated?'granted':c.mode==='basic'?'unresolved':'restricted';return{before,after,updated,warnings:[...(c.timing==='late'?['late']:[]),...(chosen&&!c.update?['missing-update']:[])],flags:Object.fromEntries(CONSENT_KEYS.map(k=>[k,updated?(c.choice==='accept'?'granted':'denied'):'denied']))};}
function consentStatus(key){return t({blocked:P('Basic gate: Google tags blocked','Basic gate: Google tags blocked'),restricted:P('Advanced: denied restrictions; cookieless pings possible','Advanced: denied restrictions; cookieless pings possible'),unknown:P('Default absent at this point: inspect actual behavior','Default absent at this point: inspect actual behavior'),granted:P('Update granted; configured tags may use granted behavior','Update granted; configured tags may use granted behavior'),unresolved:P('Choice accepted, update missing: setup unresolved','Choice accepted, update missing: setup unresolved')}[key]);}
function consentSources(){return `<p class="screen-credit">${U('Sources checked 22 Oct 2026. Ye technical practice hai; actual region, company policy, CMP aur applicable requirements separately review karo.','Sources checked 22 Oct 2026. Technical practice; review the actual region, company policy, CMP and applicable requirements separately.')}</p>${[['concepts/consent-mode','Consent mode overview'],['guides/consent','Website implementation'],['guides/consent-debugging','Tag Assistant debugging']].map(([p,l])=>`<a class="source-link" target="_blank" rel="noopener noreferrer" href="https://developers.google.com/tag-platform/security/${p}">↗ Google: ${l}</a>`).join('')}`;}
function consentTimeline(){const c=consentRecord(),r=consentSequence(c);return `<ol class="event-log"><li><div><b>1 · ${U('Fresh visit','Fresh visit')}</b><p>${c.timing==='early'?U('Demo default: chaaron flags denied, measurement se pehle.','Demo default: all four flags denied before measurement.'):U('Fault fixture: first measurement se pehle default missing.','Fault fixture: default is missing before first measurement.')}</p></div></li><li><div><b>2 · ${U('Choice se pehle event','Event before choice')}</b><p>${esc(consentStatus(r.before))}</p>${c.timing==='late'?`<p>${U('Ab late default denied set hota hai; pehle event ko undo nahi karta.','The late denied default is now set; it does not undo the first event.')}</p>`:''}</div></li><li><div><b>3 · ${U('Banner interaction','Banner interaction')}</b><p>${c.choice==='none'?U('No choice; koi update nahi.','No choice; no update.'):`${c.choice==='accept'?'Accept all':'Reject all'} · ${r.updated?U('update received','update received'):U('update missing','update missing')}`}</p></div></li><li><div><b>4 · ${U('Agla event check','Check the next event')}</b><p>${esc(consentStatus(r.after))}</p></div></li></ol><div class="formula">${CONSENT_KEYS.map(k=>`${k}: ${r.flags[k]}`).join('<br>')}</div><p class="screen-credit">${U('Flags step 4 par hain; late-default fixture mein default pehle event ke baad denied hota hai. Ye simplified design trace hai, real requests/cookies ka emulator nahi.','Flags describe step 4; the late-default fixture sets denied after the first event. This is a simplified design trace, not a requests/cookies emulator.')}</p>${r.warnings.length?`<div class="feedback error">${r.warnings.map(w=>w==='late'?U('Default too late: pehle event ko inspect aur ordering fix karo.','Default too late: inspect the first event and fix ordering.'):U('Choice aur consent state ka link broken: update test karo.','The link between choice and consent state is broken: test the update.')).join('<br>')}</div>`:''}`;}
function consentPage(){const c=consentRecord(),q=CONSENT_CASES[consentCase],a=c.answers[q.id];return `${heading('SEARCH ADS · TRACKING & DIAGNOSIS',U('Permission ka signal bhi test karo.','Test the permission signal too.'),U('Banner se tag tak: sequence dekho, fault pakro, evidence likho.','From banner to tag: inspect the sequence, find faults and record evidence.'))}<div class="action-row"><button class="btn light" data-go="clinic">← ${U('Tracking clinic','Tracking clinic')}</button></div><div class="note" style="margin:20px 0">${U('Teaching simulation only. Controls sirf fictional trace badaltay hain; is app ya kisi live website ki actual consent settings change nahi hoti. Ye exercise consent-mode ya measurement requests send nahi karti.','Teaching simulation only. Controls change a fictional trace, not actual consent settings for this app or a live site. This exercise sends no consent-mode or measurement requests.')}</div><div class="cards"><section class="card"><h2>${U('01 · Sequence lab','01 · Sequence lab')}</h2><p>${U('Is fixture mein fresh visit par denied default aur Accept all / Reject all use hotay hain. Partial choices ko neeche case mein dekho.','This fixture uses a denied default on a fresh visit and Accept all / Reject all. Explore partial choices in the case below.')}</p><div class="form-grid">${[['mode',P('Implementation design','Implementation design'),[['basic','Basic'],['advanced','Advanced']]],['timing',P('Default kab?','When is default set?'),[['early',U('First measurement se pehle','Before first measurement')],['late',U('First measurement ke baad · fault','After first measurement · fault')]]],['choice',P('Visitor ka choice','Visitor choice'),[['none',U('Abhi choose nahi kiya','No choice yet')],['accept','Accept all'],['reject','Reject all']]]].map(([key,label,options])=>`<label class="field">${esc(t(label))}<select data-consent-setting="${key}" aria-label="${esc(t(label))}">${options.map(([value,l])=>`<option value="${value}" ${c[key]===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`).join('')}</div><label class="sim-check"><input id="consent-update" type="checkbox" ${c.update?'checked':''}>${U('Banner se consent update connected','Banner is connected to the consent update')}</label><div id="consent-timeline" aria-live="polite">${consentTimeline()}</div></section><aside class="card"><h2>${U('Chaar flags, alag purposes','Four flags, different purposes')}</h2>${[['ad_storage',P('Ads se related storage','Ads-related storage')],['analytics_storage',P('Analytics se related storage','Analytics-related storage')],['ad_user_data',P('Advertising ke liye user data bhejna','Sending user data for advertising')],['ad_personalization',P('Personalized advertising','Personalized advertising')]].map(([k,v])=>`<div class="coverage-item"><b>${k}</b><span>${esc(t(v))}</span></div>`).join('')}<p>${U('Consent mode consent banner nahi banata. Built-in checks aur custom/non-Google tags ki gating separately inspect karo. Basic/advanced choice ko company requirements se decide karo.','Consent mode does not create a consent banner. Inspect built-in checks and custom/non-Google tag gating separately. Choose basic/advanced against company requirements.')}</p></aside></div><section class="card" style="margin-top:22px"><h2>${U('02 · Fault decision','02 · Fault decision')} · ${consentCase+1}/6</h2><div class="tabs">${CONSENT_CASES.map((x,i)=>`<button data-consent-case="${i}" class="${i===consentCase?'active':''}">${c.answers[x.id]===x.answer?'✓ ':''}${i+1}</button>`).join('')}</div><h3>${esc(t(q.title))}</h3><div class="example">${esc(t(q.fact))}</div><div class="quiz-options">${q.options.map((o,i)=>`<button class="option ${a===i?(i===q.answer?'correct':'wrong'):''}" data-consent-answer="${i}">${esc(t(o))}</button>`).join('')}</div>${a===undefined?'':`<div class="feedback ${a===q.answer?'':'error'}">${a===q.answer?'✓ ':''}${esc(t(q.why))}</div>`}</section><section class="card" style="margin-top:22px"><h2>${U('03 · Apna verification record','03 · Your verification record')}</h2><ol class="steps"><li>${U('Clean visit: default aur first event ki order dekho.','Clean visit: inspect default and first-event ordering.')}</li><li>${U('No choice, Accept, Reject, partial choice aur withdrawal test karo.','Test no choice, Accept, Reject, partial choices and withdrawal.')}</li><li>${U('Tag Assistant state ko network/storage evidence se compare karo. Navigation, returning visit aur configured regions bhi test karo.','Compare Tag Assistant state with network/storage evidence. Test navigation, returning visits and configured regions too.')}</li></ol><label class="field">${U('Device/date → expected → observed → evidence → owner/fix → retest','Device/date → expected → observed → evidence → owner/fix → retest')}<textarea id="consent-notes" rows="5" maxlength="5000">${esc(c.notes)}</textarea></label><small id="consent-save" role="status">${U('Notes browser mein autosave; fictional data use karo.','Notes autosave in this browser; use fictional data.')}</small><div class="action-row"><button class="btn light" id="consent-export">${U('Practice record download','Download practice record')}</button></div></section>${consentSources()}${footer()}`;}
function bindConsent(){const c=consentRecord();$$('[data-consent-setting]').forEach(x=>x.onchange=()=>{c[x.dataset.consentSetting]=x.value;save();$('#consent-timeline').innerHTML=consentTimeline();});$('#consent-update').onchange=e=>{c.update=e.target.checked;save();$('#consent-timeline').innerHTML=consentTimeline();};$$('[data-consent-case]').forEach(x=>x.onclick=()=>{consentCase=+x.dataset.consentCase;const y=window.scrollY;render();window.scrollTo(0,y);});$$('[data-consent-answer]').forEach(x=>x.onclick=()=>{c.answers[CONSENT_CASES[consentCase].id]=+x.dataset.consentAnswer;save();const y=window.scrollY;render();window.scrollTo(0,y);});$('#consent-notes').oninput=e=>{c.notes=e.target.value.slice(0,5000);save();$('#consent-save').textContent=storageOK?U('Saved in this browser','Saved in this browser'):U('Storage unavailable; record download karo','Storage unavailable; download your record');};$('#consent-export').onclick=()=>download('ads-asaan-consent-practice.json',{simulation:true,record:c,trace:consentSequence(c),notice:'Fictional design trace; not a network test, CMP, legal audit or compliance certificate.'});}
